        int64_t l = ranges[i].first;
        int64_t r = ranges[i].second;

        // Check if current range overlaps or is adjacent to [cur_l, cur_r]
        // Overlap: l <= cur_r
        // Adjacent: l == cur_r + 1 (but avoid overflow)
        // Combined condition: l <= cur_r OR (l == cur_r + 1)
        // Safe check: l <= cur_r OR (cur_r < INT64_MAX && l == cur_r + 1)
        // Equivalent safe form: l <= cur_r OR (cur_r < INT64_MAX && l - 1 == cur_r)
