        // But cur_r + 1 can overflow if cur_r == INT64_MAX.
        // Use: l <= cur_r OR (cur_r < INT64_MAX && l == cur_r + 1)
        // Since we check cur_r < INT64_MAX first, cur_r + 1 is safe.

        bool overlaps_or_adjacent = false;
        if (l <= cur_r) {
            overlaps_or_adjacent = true;
        } else if (cur_r < INT64_MAX && l == cur_r + 1) {
            overlaps_or_adjacent = true;
        }

        if (overlaps_or_adjacent) {
            if (r > cur_r) {
                cur_r = r;
            }
        } else {
            merged.emplace_back(cur_l, cur_r);
            cur_l = l;
            cur_r = r;
        }
